const table = () => ({ k: 'table', m: new Map(), hdr: false })
const scalar = (k, v) => ({ k, v })

class ConfError extends Error {
  constructor(msg) { super(msg); this.isConfError = true }
}

const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /^[A-Za-z0-9_-]$/.test(c)
const INT = /^[+-]?[0-9]+(_[0-9]+)*$/
const FLOAT = /^[+-]?[0-9]+(_[0-9]+)*(\.[0-9]+(_[0-9]+)*)?([eE][+-]?[0-9]+(_[0-9]+)*)?$/

class LineParser {
  constructor(s) { this.s = s; this.i = 0 }
  peek() { return this.s[this.i] }
  ws() { while (isWs(this.s[this.i])) this.i++ }
  atEnd() { // after ws: end of line or comment
    const c = this.s[this.i]
    return c === undefined || c === '#' || c === ';'
  }
  fail(m) { throw new ConfError(m) }

  quoted() {
    const q = this.s[this.i++]
    let out = ''
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) this.fail('unterminated string')
      this.i++
      if (c === q) return out
      if (q === "'" || c !== '\\') { out += c; continue }
      const e = this.s[this.i]
      if (e === undefined) this.fail('unterminated string')
      this.i++
      if (e === '"') out += '"'
      else if (e === '\\') out += '\\'
      else if (e === 'n') out += '\n'
      else if (e === 't') out += '\t'
      else if (e === 'r') out += '\r'
      else if (e === '0') out += '\0'
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) this.fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else this.fail('invalid escape \\' + String.fromCodePoint(this.s.codePointAt(this.i - 1)))
    }
  }

  name() {
    const c = this.peek()
    if (c === '"' || c === "'") return this.quoted()
    const st = this.i
    while (isBare(this.s[this.i])) this.i++
    if (this.i === st) this.fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.peek() === '.') {
        this.i++
        this.ws()
        parts.push(this.name())
      } else { this.i = save; return parts }
    }
  }

  value(base) {
    this.ws()
    const c = this.peek()
    if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') this.fail('expected a value')
    if (c === '"' || c === "'") return scalar('string', this.quoted())
    if (c === '[') return this.array(base)
    if (c === '{') return this.inline(base)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]};'.includes(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true') return scalar('boolean', true)
    if (w === 'false') return scalar('boolean', false)
    if (INT.test(w)) return scalar('integer', Number(w.replace(/_/g, '')))
    if (FLOAT.test(w)) return scalar('float', Number(w.replace(/_/g, '')))
    this.fail('invalid value ' + w)
  }

