    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.atEnd()) this.fail('unterminated array')
      if (this.peek() === ']') { this.i++; return { k: 'array', items } }
      items.push(this.value(base))
      this.ws()
      const c = this.peek()
      if (c === ',') this.i++
      else if (c === ']') { this.i++; return { k: 'array', items } }
      else this.fail('unterminated array')
    }
  }

  inline(base) {
    this.i++
    const t = table()
    this.ws()
    if (this.peek() === '}') { this.i++; return t }
    for (;;) {
      this.ws()
      if (this.atEnd()) this.fail('unterminated inline table')
      const parts = this.dotted()
      this.ws()
      if (this.peek() !== '=') this.fail('expected = in an inline table')
      this.i++
