const j = (p) => p.join('.')

function walk(tbl, base, parts) {
  for (let i = 0; i < parts.length - 1; i++) {
    const n = tbl.m.get(parts[i])
    if (n === undefined) {
      const t = table()
      tbl.m.set(parts[i], t)
      tbl = t
    } else if (n.k === 'table') tbl = n
    else if (n.k === 'aot') tbl = n.items[n.items.length - 1]
    else throw new ConfError(`${j(base.concat(parts.slice(0, i + 1)))} is not a table`)
  }
  return tbl
}

function assign(tbl, base, parts, v) {
  const t = walk(tbl, base, parts)
  const last = parts[parts.length - 1]
  if (t.m.has(last)) throw new ConfError(`key ${j(base.concat(parts))} is defined twice`)
  t.m.set(last, v)
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const root = table()
  let cur = root
  let curPath = []
  lines.forEach((line, idx) => {
    try {
      const r = parseLine(line, root, cur, curPath)
      if (r) { cur = r.cur; curPath = r.path }
    } catch (e) {
      if (e && e.isConfError) e.message = `line ${idx + 1}: ${e.message}`
      throw e
    }
  })
  return root
}

function parseLine(line, root, cur, curPath) {
  const p = new LineParser(line)
  p.ws()
  const c = p.peek()
  if (c === undefined || c === '#' || c === ';') return null
  if (c === '[') {
    const aot = line[p.i + 1] === '['
    p.i += aot ? 2 : 1
    p.ws()
    const parts = p.dotted()
    p.ws()
    for (let n = aot ? 2 : 1; n > 0; n--) {
      if (p.peek() !== ']') p.fail('unterminated table header')
      p.i++
    }
    p.ws()
    if (!p.atEnd()) p.fail('trailing text after a table header')
    const t = walk(root, [], parts)
    const last = parts[parts.length - 1]
    const ex = t.m.get(last)
    if (aot) {
      if (ex === undefined) {
        const a = { k: 'aot', items: [] }
        t.m.set(last, a)
        const nt = table(); nt.hdr = true
        a.items.push(nt)
        return { cur: nt, path: parts }
      }
      if (ex.k !== 'aot') p.fail(`${j(parts)} is not an array of tables`)
      const nt = table(); nt.hdr = true
      ex.items.push(nt)
      return { cur: nt, path: parts }
    }
    if (ex === undefined) {
      const nt = table(); nt.hdr = true
      t.m.set(last, nt)
      return { cur: nt, path: parts }
    }
    if (ex.k !== 'table') p.fail(`${j(parts)} is not a table`)
    if (ex.hdr) p.fail(`table ${j(parts)} is defined twice`)
    ex.hdr = true
    return { cur: ex, path: parts }
  }
  const parts = p.dotted()
  p.ws()
  if (p.peek() !== '=') p.fail('expected key = value')
  p.i++
  const v = p.value(curPath.concat(parts))
  p.ws()
  if (!p.atEnd()) p.fail('trailing text after a value')
  assign(cur, curPath, parts, v)
  return null
}
